// marshalOnboardingOnboardingStateToOnboardingStateResponseBody builds a value
// of type *OnboardingStateResponseBody from a value of type
// *onboarding.OnboardingState.
func marshalOnboardingOnboardingStateToOnboardingStateResponseBody(v *onboarding.OnboardingState) *OnboardingStateResponseBody {
	res := &OnboardingStateResponseBody{
		Done: v.Done,
	}
	if v.Answers != nil {
		res.Answers = marshalOnboardingOnboardingAnswersToOnboardingAnswersResponseBody(v.Answers)
	}
	if v.NextStep != nil {
		res.NextStep = marshalOnboardingOnboardingStepToOnboardingStepResponseBody(v.NextStep)
	}
	if v.Steps != nil {
		res.Steps = make([]*OnboardingStepResponseBody, len(v.Steps))
		for i, val := range v.Steps {
			if val == nil {
				res.Steps[i] = nil
				continue
			}
			res.Steps[i] = marshalOnboardingOnboardingStepToOnboardingStepResponseBody(val)
		}
	} else {
		res.Steps = []*OnboardingStepResponseBody{}
	}

	return res
}

